#define KELLY_DECOMP_FULL_FEMENU_ENTRY
#include "KS/SRC/ks/FEMenu_shared.h"

typedef int device_id_t;
typedef int axis_id_t;
typedef float rational_t;

class input_device {
public:
    virtual device_id_t get_id() const = 0;
    virtual int get_axis_count() const = 0;
    virtual axis_id_t get_axis_id(int axis) const = 0;
    virtual rational_t get_axis_state(axis_id_t axis, int control_axis) const = 0;
    virtual rational_t get_axis_old_state(axis_id_t axis, int control_axis) const = 0;
    virtual rational_t get_axis_delta(axis_id_t axis, int control_axis) const = 0;
    virtual bool is_connected() const { return false; }
};

class input_mgr {
    char data_before_joysticks[36];
    input_device *joystick_devices[9];

public:
    static input_mgr *inst();
    inline input_device *get_joystick_index(int index) const {
        return joystick_devices[index];
    }
};

extern input_mgr *input_manager;
inline input_mgr *input_mgr::inst() { return input_manager; }

class GraphicalMenuSystem;

class MultiplayerMenu : public FEMenu {
public:
    enum {
        MultiPushEntry,
        MultiHeadToHeadEntry,
        MultiTimeAttackEntry,
        MultiEnd
    };

    GraphicalMenuSystem *sys;
    FEMenuEntry *entry[MultiEnd];

private:
    void UpdateDisable();
};

__asm__(".equ input_manager, 0x0046B7B0");

void MultiplayerMenu::UpdateDisable()
{
    int num_controllers = 0;

    for( int j = 0; j < 8; j++ )
    {
        input_device* joy = input_mgr::inst()->get_joystick_index( j );
        if( joy && joy->is_connected() )
            num_controllers++;
    }

    entry[MultiHeadToHeadEntry]->Disable( num_controllers < 2 );
    entry[MultiPushEntry]->Disable( num_controllers < 2 );

    if(highlighted->GetDisable())
    {
        FEMenuEntry* tmp = highlighted->next;
        if(!tmp) tmp = entries;
        while(tmp != highlighted)
        {
            if(!tmp->GetDisable())
            {
                setHigh(tmp);
                break;
            }
            tmp = tmp->next;
            if(!tmp) tmp = entries;
        }
    }
}
